onChange.script:
if len(self.props.selectionData)>0:
	selection=self.props.selectionData[0].value	

	if 'filename' in selection.keys():
		self.view.custom.type='file'
		parentPath=self.view.custom.fileSystem.path
		directory=selection['directory']
		filename=selection['filename']
		if directory is None:
			self.view.custom.loadPath='{}/{}'.format(parentPath,filename)
		else:
			self.view.custom.loadPath='{}/{}/{}'.format(parentPath,directory,filename)

	elif 'directory' in selection.keys():
		self.view.custom.type='dir'
		parentPath=self.view.custom.fileSystem.path
		directory=selection['directory']
		self.view.custom.loadPath='{}/{}'.format(parentPath,directory)

	else:
		self.view.custom.loadPath=''
		self.view.custom.type=''
else:
	self.view.custom.loadPath=''
	self.view.custom.type=''

